class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def mergeAscDesc(a, b):
    l1 = build(a)
    # reverse b so that it becomes non-decreasing
    l2 = None
    cur = build(b)
    while cur:
        nxt = cur.next
        cur.next = l2
        l2 = cur
        cur = nxt
    dummy = ListNode()
    tail = dummy
    while l1 and l2:
        if l2.val < l1.val:
            tail.next = l2
            l2 = l2.next
        else:
            tail.next = l1
            l1 = l1.next
        tail = tail.next
    tail.next = l1 if l1 else l2
    return dump(dummy.next)
